+  const parsedRows = markdown
+    .trim()
+    .split('\n')
+    .map(parseRow);
+
+  const columnCount = parsedRows[0]?.length ?? 0;
+  if (parsedRows.some((row) => row.length !== columnCount)) {
+    throw new Error('Cannot parse ragged markdown table');
+  }
+
+  return parsedRows.filter((row, index) => index !== 1 || !isAlignmentRow(row));
+}
+
+function parseRow(line) {
+  let source = line.trim();
+
+  if (source.startsWith('|')) {
+    source = source.slice(1);
+  }
+
+  if (source.endsWith('|') && !isEscaped(source, source.length - 1)) {
+    source = source.slice(0, -1);
+  }
+
+  const cells = [];
+  let cell = '';
+
+  for (let index = 0; index < source.length; index += 1) {
+    const char = source[index];
+
+    if (char === '|' && !isEscaped(source, index)) {
+      cells.push(cell.trim());
+      cell = '';
+      continue;
+    }
+
+    if (char === '|' && isEscaped(source, index)) {
+      cell = cell.slice(0, -1);
+    }
+
+    cell += char;
+  }
+
+  cells.push(cell.trim());
+  return cells;
+}
+
+function isEscaped(source, index) {
+  let backslashes = 0;
+
+  for (let cursor = index - 1; cursor >= 0 && source[cursor] === '\\'; cursor -= 1) {
+    backslashes += 1;
+  }
+
+  return backslashes % 2 === 1;
+}
+
+function isAlignmentRow(row) {
+  return row.every((cell) => /^:?-{3,}:?$/.test(cell));
 }
